import styled from "styled-components";

import { ToolSpan, KnowledgeBaseSpan, Span } from "../../../types/playground";
import { DivFlexRow } from "../../components/elements/formelements";
import Accordion from "../../components/Accordion";
import ToolIcon from "../../../icons/ToolIcon";
import KnowledgeBaseIcon from "../../../icons/KnowledgeBaseIcon";
import { getDurationString } from "../../../utils/timeUtils";

const isToolSpan = (span: Span): span is ToolSpan => "toolName" in span;
const isKnowledgeBaseSpan = (span: Span): span is KnowledgeBaseSpan => "kbDisplayName" in span;

interface ReferencesAndToolsProps {
    spans: Span[];
}

const SpanDuration = styled.span`
    font-size: 10px;
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
`;

const ReferencesAndTools: React.FC<ReferencesAndToolsProps> = ({ spans }) => {
    const renderSpan = (span: Span) => {
        let title, icon;
        if (isToolSpan(span)) {
            icon = <ToolIcon />;
            title = span.toolName;
        } else if (isKnowledgeBaseSpan(span)) {
            title = span.kbDisplayName;
            icon = <KnowledgeBaseIcon />;
        }
        return (
            <DivFlexRow key={span.spanId} marginTop={8} alignItems="center">
                <div>{icon}</div>
                <div>
                    <div>{title}</div>
                    <SpanDuration>{getDurationString(span.durationMilliseconds)}</SpanDuration>
                </div>
            </DivFlexRow>
        );
    };

    return (
        <DivFlexRow marginTop={8}>
            <Accordion title="References & tools">{spans.map((span) => renderSpan(span))}</Accordion>
        </DivFlexRow>
    );
};

export default ReferencesAndTools;
