import { useCallback, useEffect, useState } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";

import { useDependentDocumentChanges } from "@src/hooks/useDependentDocumentChanges";
import AppThemeProvider from "@src/ui/components/AppThemeProvider";
import { CenteredLoadingSpinner } from "@src/ui/components/CenteredLoadingSpinner";
import { PageContainer, PageContent } from "@src/ui/components/PageContainers";
import { createDocumentEditorComponent } from "@src/ui/utils/componentLoader";

import { Agent, AgentDocument } from "@src/types/agent";
import { createNewAgentDocument, testRuntimeConnection, updateAgentDocument } from "@src/utils/agentUtils";

import AgentEditor from "./agentEditor";

const initialAgentDocument: AgentDocument = createNewAgentDocument();

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}

const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;
    const [isLoaded, setIsLoaded] = useState(false);
    const [agentDocument, setAgentDocument] = useState<AgentDocument>(initialAgentDocument);
    const [documentVersion, setDocumentVersion] = useState(0);
    const [isRuntimeConnected, setIsRuntimeConnected] = useState(false);
    const [showUnsavedChangesWarning, setShowUnsavedChangesWarning] = useState(false);
    const dependentIds = [
        documentId,
        agentDocument.contents.model?.documentId,
        ...agentDocument.contents.tools.map((tool) => tool.document.documentId),
    ].filter((id): id is string => !!id);

    const watchDomainModelModules = agentDocument.contents.entity
        ? [agentDocument.contents.entity?.qualifiedName?.split(".")?.[0]]
        : undefined;

    useEffect(() => {
        documentApi
            .getDocumentById<Agent>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<Agent>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    setIsLoaded(true);
                    setAgentDocument(documentFromModel.document);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(async (err) => {
                await messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
                setIsLoaded(true);
            });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [documentVersion]);

    const onDependentDocumentsChanged = useCallback(
        (changes: string[]) => {
            if (changes.some((id) => id === documentId)) {
                setDocumentVersion((v) => v + 1);
            }
            setShowUnsavedChangesWarning(true);
        },
        [documentId]
    );

    useDependentDocumentChanges({
        studioPro,
        dependentIds,
        onDependentDocumentsChanged,
        watchProjectSettings: true,
        watchDomainModelModules,
    });

    useEffect(() => {
        const handleConnectionChanged = (e: { isConnected: boolean }) => {
            setIsRuntimeConnected(e.isConnected);
            /* Clear the warning when there is change in runtime since:
                - if runtime gets connected, it will force the user to persist the unsaved changes
                - if runtime got disconnected, then the warning is not relevant
            */
            setShowUnsavedChangesWarning(false);
        };

        studioPro.runtime.controller.addEventListener("connectionChanged", handleConnectionChanged);

        return () => {
            studioPro.runtime.controller.removeEventListener("connectionChanged", handleConnectionChanged);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        // Test the runtime connection on initial load to handle the case where the user opens the editor while the runtime is already connected
        testRuntimeConnection(studioPro).then((isConnected) => {
            setIsRuntimeConnected(isConnected);
        });
    }, [studioPro]);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <CenteredLoadingSpinner />}
                {isLoaded && (
                    <PageContent>
                        <AgentEditor
                            agentDocument={agentDocument}
                            isRuntimeConnected={isRuntimeConnected}
                            showUnsavedChangesWarning={showUnsavedChangesWarning && isRuntimeConnected}
                            studioPro={studioPro}
                            updateStudioProDocument={updateAgentDocument(studioPro, documentId)}
                        ></AgentEditor>
                    </PageContent>
                )}
            </PageContainer>
        </AppThemeProvider>
    );
};

export { App };
export const component: IComponent = createDocumentEditorComponent(App);
