import React from "react";

import { DivFlexColumn, DivFlexRow, StyledBadgeLabel, LabelWrapper, StyledTextArea } from "./elements/formelements";

interface TextAreaBadgedProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange: (value: string) => void;
    readOnly?: boolean;
    badgeBackgroundColor: string;
    badgeBorderColor: string;
}

const TextAreaBadged: React.FC<TextAreaBadgedProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    readOnly = false,
    badgeBackgroundColor,
    badgeBorderColor,
}) => {
    return (
        <DivFlexRow>
            {label && (
                <DivFlexColumn>
                    <LabelWrapper>
                        <StyledBadgeLabel
                            title={label}
                            backgroundcolor={badgeBackgroundColor}
                            bordercolor={badgeBorderColor}
                        >
                            {"{{" + label + "}}"}
                        </StyledBadgeLabel>
                    </LabelWrapper>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <StyledTextArea value={value} readOnly={readOnly} onChange={onChange} ariaLabel={ariaLabel} />
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextAreaBadged;
