import React from "react";
import styled from "styled-components";
import TextAreaBadged from "./TextAreaBadged";
import { TestVariable } from "../../types/agent";
import { HighlightRule } from "./TextAreaLabeled";

const StyledDiv = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
`;

interface VariablesListProps {
    variables: TestVariable[];
    highlightRules: HighlightRule[];
    onVariableChange: (index: number, value: string) => void;
}

const VariablesList: React.FC<VariablesListProps> = ({ variables, highlightRules, onVariableChange }) => {
    return variables.length > 0 ? (
        <StyledDiv>
            {variables.map((variable, index) => (
                <TextAreaBadged
                    key={`${variable.key}-${index}`}
                    label={variable.key}
                    ariaLabel={"variable-" + variable.key}
                    value={variable.value}
                    onChange={(value: string) => onVariableChange(index, value)}
                    badgeBackgroundColor={highlightRules[index]?.style?.backgroundColor || "initial"}
                    badgeBorderColor={highlightRules[index]?.style?.borderColor || "initial"}
                />
            ))}
        </StyledDiv>
    ) : null;
};

export default VariablesList;
